"""Accounting export validation and isolated ERP gateway delivery tests."""

import io
import json
import urllib.error
from contextlib import contextmanager
from dataclasses import replace
from unittest.mock import Mock

import pytest

from billing import export, invoice


@pytest.fixture
def inv():
    return invoice.FIXTURES["INV-2024-0107"]()


@pytest.mark.parametrize("customer,message", [
    ("No registration", "no GSTIN"),
    ("Buyer (GSTIN 00ABCDE1234F1Z5)", "invalid state code"),
    ("Buyer (GSTIN 39ABCDE1234F1Z5)", "invalid state code"),
    ("Buyer (GSTIN ABABCDE1234F1Z5)", "invalid state code"),
])
def test_gstin_validation(inv, customer, message):
    with pytest.raises(export.ExportError, match=message):
        export.gstin_of(replace(inv, customer=customer))


def test_empty_invoice_is_rejected(inv):
    with pytest.raises(export.ExportError, match="no lines"):
        export.totals(replace(inv, lines=[], proration=None))


def test_ledger_rejects_unsupported_currency(inv):
    with pytest.raises(export.ExportError, match="supports.*INR"):
        export.ledger_csv([inv], currency="USD")


def test_ledger_rejects_net_credit_notes(inv):
    credit_note = replace(inv, lines=[("Refund", -100)], proration=None)
    with pytest.raises(export.ExportError, match="issue a credit note"):
        export.ledger_csv([credit_note])


def test_ledger_rejects_duplicate_numbers(inv):
    with pytest.raises(export.ExportError, match="duplicate invoice numbers"):
        export.ledger_csv([inv, inv])


def test_ledger_sorts_invoices(inv):
    earlier = invoice.FIXTURES["INV-2024-0042"]()
    same_day = replace(inv, number="INV-2024-0106")
    rows = export.ledger_csv([inv, same_day, earlier]).splitlines()
    assert [row.split(",")[0] for row in rows[1:]] == [earlier.number, same_day.number, inv.number]


def test_erp_line_limit_counts_proration_credit(inv):
    with pytest.raises(export.ExportError, match="100 lines exceeds.*99"):
        export.erp_payload(replace(inv, lines=[("Service", 100)] * 99))
    doc = json.loads(export.erp_payload(replace(inv, lines=[("Service", 100)] * 98)))
    assert len(doc["lines"]) == 99


@contextmanager
def response(document):
    yield io.BytesIO(json.dumps(document).encode())


def http_error(code, document=None):
    return urllib.error.HTTPError(
        "https://erp.example/invoices", code, "error", {},
        io.BytesIO(json.dumps(document).encode() if document is not None else b""),
    )


@pytest.fixture
def gateway(monkeypatch):
    urlopen = Mock()
    sleep = Mock()
    monkeypatch.setattr(export.urllib.request, "urlopen", urlopen)
    monkeypatch.setattr(export.time, "sleep", sleep)
    return urlopen, sleep


def test_delivery_sends_upgrade_payload_with_auth_and_idempotency(inv, gateway):
    urlopen, sleep = gateway
    urlopen.return_value = response({"document_id": "ERP-107"})
    assert export.send_to_erp(inv, url="https://erp.example/invoices", token="test-token") == "ERP-107"
    request = urlopen.call_args.args[0]
    assert request.full_url == "https://erp.example/invoices"
    assert request.get_method() == "POST"
    assert request.get_header("Authorization") == "Bearer test-token"
    assert request.get_header("Content-type") == "application/json"
    assert request.get_header("Idempotency-key") == "inv-INV-2024-0107"
    assert json.loads(request.data) == json.loads(export.erp_payload(inv))
    assert urlopen.call_args.kwargs == {"timeout": 20}
    sleep.assert_not_called()


def test_delivery_retries_transient_errors_with_backoff(inv, gateway):
    urlopen, sleep = gateway
    urlopen.side_effect = [
        http_error(429), http_error(503), urllib.error.URLError("offline"),
        response({"document_id": "ERP-107"}),
    ]
    assert export.send_to_erp(inv) == "ERP-107"
    assert urlopen.call_count == 4
    assert [call.args[0] for call in sleep.call_args_list] == [1, 4, 15]
    assert all(call.args[0].get_header("Authorization") is None for call in urlopen.call_args_list)
    assert len({call.args[0].data for call in urlopen.call_args_list}) == 1


@pytest.mark.parametrize("code", [400, 401, 422])
def test_delivery_does_not_retry_permanent_rejection(inv, gateway, code):
    urlopen, sleep = gateway
    urlopen.side_effect = http_error(code)
    with pytest.raises(export.DeliveryError, match=f"rejected.*{code}"):
        export.send_to_erp(inv)
    assert urlopen.call_count == 1
    sleep.assert_not_called()


def test_delivery_returns_existing_document_on_conflict(inv, gateway):
    urlopen, sleep = gateway
    urlopen.side_effect = http_error(409, {"document_id": "ERP-existing"})
    assert export.send_to_erp(inv) == "ERP-existing"
    sleep.assert_not_called()


@pytest.mark.parametrize("document", [None, {}])
def test_delivery_rejects_conflict_without_document_id(inv, gateway, document):
    urlopen, sleep = gateway
    urlopen.side_effect = http_error(409, document)
    with pytest.raises(export.DeliveryError, match="duplicate delivery without a document id"):
        export.send_to_erp(inv)
    sleep.assert_not_called()


def test_delivery_rejects_success_without_document_id(inv, gateway):
    urlopen, sleep = gateway
    urlopen.return_value = response({})
    with pytest.raises(export.DeliveryError, match="returned no document_id"):
        export.send_to_erp(inv)
    sleep.assert_not_called()


@pytest.mark.parametrize("kind", ["http", "connection"])
def test_delivery_stops_after_maximum_attempts(inv, gateway, kind):
    urlopen, sleep = gateway
    urlopen.side_effect = http_error(503) if kind == "http" else urllib.error.URLError("offline")
    message = "HTTP 503" if kind == "http" else "connection error: offline"
    with pytest.raises(export.DeliveryError, match=f"failed after 4 attempts.*{message}"):
        export.send_to_erp(inv)
    assert urlopen.call_count == export.MAX_ATTEMPTS
    assert sleep.call_count == export.MAX_ATTEMPTS - 1
